import { Meta, StoryObj } from "@storybook/react";
import { Label, LabelProps } from "./label";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const textSizes = ["xxs", "xs", "s", "m", "l"] satisfies Array<LabelProps["textSize"]>;

const meta = {
  title: "Primitives/Label",
  component: Label,
  parameters: {
    docs: {
      description: {
        component:
          "Small badge with a themed background, used to tag cards and list items (queue time, sold out, " +
          "opening hours). The wrapper is a plain block element without its own sizing, so consumers place it in a " +
          "positioned or flex container to make it hug its text; the stories do the same with an inline wrapper. " +
          "Background, padding, radius and text color all come from the component-label theme tokens.",
      },
    },
  },
  args: {
    title: "Fullbokat",
    textSize: "s",
  },
  // The badge is a block element, so without a shrinking parent it would stretch across the whole canvas.
  render: (args) => (
    <div style={{ display: "inline-flex" }}>
      <Label {...args} />
    </div>
  ),
} satisfies Meta<typeof Label>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantTextSize: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="textSize" variantType="prop">
      {textSizes.map((textSize) => (
        <Variant key={textSize} label={textSize}>
          <div style={{ display: "inline-flex" }}>
            <Label {...args} textSize={textSize} />
          </div>
        </Variant>
      ))}
    </ShowcaseLayout>
  ),
};
